def transform(grid):
    h, w = len(grid), len(grid[0])

    # Complete repeating sequences of solid-color rows.
    if all(len(set(row)) == 1 for row in grid):
        vals = [row[0] for row in grid]
        for p in range(1, h + 1):
            pattern = {}
            for r, v in enumerate(vals):
                if v != 0 and r % p in pattern and pattern[r % p] != v:
                    break
                if v != 0:
                    pattern[r % p] = v
            else:
                if pattern:
                    for r in range(h):
                        if r % p not in pattern:
                            pattern[r % p] = next(iter(pattern.values()))
                    return [[pattern[r % p]] * w for r in range(h)]

    # Look for a repeating pattern of diagonal stripes.
    candidates = []
    for mode in ("difference", "sum"):
        def key(r, c, p):
            return (c - r if mode == "difference" else r + c) % p

        for p in range(1, max(h, w) + 1):
            pattern = {}
            valid = True
            for r in range(h):
                for c in range(w):
                    v = grid[r][c]
                    if v:
                        k = key(r, c, p)
                        if k in pattern and pattern[k] != v:
                            valid = False
                            break
                        pattern[k] = v
                if not valid:
                    break
            if valid and pattern:
                candidates.append((p, mode, pattern))
                break

    if candidates:
        p, mode, pattern = min(candidates, key=lambda x: x[0])
        for k in range(p):
            if k not in pattern:
                pattern[k] = next(iter(pattern.values()))

        def stripe_key(r, c):
            return (c - r if mode == "difference" else r + c) % p

        return [[pattern[stripe_key(r, c)] for c in range(w)] for r in range(h)]

    return [row[:] for row in grid]
